import { createTransferWorkspace } from './src/workspace.js';

const target = new EventTarget();
let starts = 0;
const feed = {
  target,
  start() {
    starts++;
    target.dispatchEvent(new CustomEvent('progress', { detail: `cached-${starts}` }));
  },
  decode(detail) { return { seq: detail, loaded: 1 }; },
};
const seen = { audit: [], shown: [], queued: [] };
const workspace = createTransferWorkspace({
  transport() {}, onCancel() {}, record() {},
  showQueued(value) { seen.queued.push(value); },
  recordProgress(value) { seen.audit.push(value); },
  showProgress(value) { seen.shown.push(value); },
});
const file = { id: 'a', progressFeed: feed };
workspace.select(file);
target.dispatchEvent(new CustomEvent('progress', { detail: 'later' }));
workspace.hide();
target.dispatchEvent(new CustomEvent('progress', { detail: 'ignored' }));
workspace.select(file);
if (seen.audit.length !== 3 || seen.shown.length !== 3 || starts !== 2) throw new Error(JSON.stringify({ seen, starts }));

const delayedTarget = new EventTarget();
let settle;
const delayedFeed = {
 target: delayedTarget,
 start() { delayedTarget.dispatchEvent(new CustomEvent('progress', { detail: 'early' })); },
 decode() { return new Promise(resolve => { settle = resolve; }); },
};
const delayed = { audit: [], shown: [] };
const second = createTransferWorkspace({
 transport() {}, onCancel() {}, record() {}, showQueued() {},
 recordProgress(value) { delayed.audit.push(value); },
 showProgress(value) { delayed.shown.push(value); },
});
second.select({ id: 'b', progressFeed: delayedFeed });
second.hide();
settle({ seq: 1, loaded: 1 });
await Promise.resolve();
if (delayed.audit.length !== 1 || delayed.shown.length !== 0) throw new Error(JSON.stringify(delayed));
console.log('progress lifecycle checks passed');
