import { createTransferWorkspace } from './src/workspace.js';
const event = detail => { const e = new Event('progress'); Object.defineProperty(e, 'detail', { value: detail }); return e; };
const target = new EventTarget();
const pending = [];
const feed = { target, start() {}, decode(detail) { return new Promise(resolve => pending.push(() => resolve({ seq: detail, loaded: 1 }))); } };
const audit = [], visible = [];
const workspace = createTransferWorkspace({ transport() {}, onCancel() {}, record() {}, showQueued() {}, recordProgress(v) { audit.push(v); }, showProgress(v) { visible.push(v); } });
workspace.select({ id: 'retry', progressFeed: feed });
target.dispatchEvent(event('old'));
workspace.retry();
target.dispatchEvent(event('new'));
pending.splice(0).forEach(resolve => resolve());
await Promise.resolve();
if (audit.length !== 2 || visible.length !== 1 || visible[0].frame.seq !== 'new') throw new Error(JSON.stringify({ audit, visible }));
console.log('retry progress check passed');
